CREATE OR REPLACE TABLE "FC Plan Months" ("Versions" UInt8, "Years" UInt8, v Float64) ENGINE = Memory;
INSERT INTO "FC Plan Months" SETTINGS insert_null_as_default = 0
SELECT * FROM (
