CREATE OR REPLACE TABLE "COGS ACT" ("Customer" Int32, "SKU" Int32, "Years" UInt8, "Months" UInt8, v Float64) ENGINE = Memory;
INSERT INTO "COGS ACT" SETTINGS insert_null_as_default = 0
SELECT * FROM (
    SELECT d."Customer" AS "Customer", d."SKU" AS "SKU", d."Years" AS "Years", d."Months" AS "Months", ((d.p0_v * d.p1_v) * d.p2_v) AS v
    FROM (SELECT p0."Customer" AS "Customer", p0."SKU" AS "SKU", p0."Years" AS "Years", p0."Months" AS "Months", p0.v AS p0_v, p1.v AS p1_v, p2.v AS p2_v FROM (SELECT s."Customer" AS "Customer", s."SKU" AS "SKU", s."Years" AS "Years", s."Months" AS "Months", s.v AS v FROM "Volume ACT" s) p0 JOIN (SELECT s."SKU" AS "SKU", s."Years" AS "Years", s.v AS v FROM "IMPORT Standard Cost" AS s FINAL) p1 ON p1."SKU" = p0."SKU" AND p1."Years" = p0."Years" JOIN "flat Customer" g_0 ON g_0."Customer" = p0."Customer" JOIN (SELECT s."Years" AS "Years", s."Months" AS "Months", s."Currency" AS "Currency", s.v AS v FROM "IMPORT FX Rate" AS s FINAL) p2 ON p2."Years" = p0."Years" AND p2."Months" = p0."Months" AND p2."Currency" = g_0."Currency") d
) WHERE v IS NOT NULL;

-- @table "Volume LY"
